#!/usr/bin/env python3
"""Generate the twelve Stage 02J-W qualification reports and final integrity ledger."""

from __future__ import annotations

import hashlib
import json
from pathlib import Path
from typing import Any

REPO=Path(__file__).resolve().parents[4]
STAGE=REPO/"stage_02_Particle_Interaction_Operator"; ROOT=STAGE/"05_dataset/blind_multifamily_pair_scope_v1_0"; REPORTS=STAGE/"07_reports"


def load(path: Path)->dict[str,Any]: return json.loads(path.read_text(encoding="utf-8"))
def sha(path: Path)->str: return "sha256:"+hashlib.sha256(path.read_bytes()).hexdigest()
def write(path: Path,text: str)->None:
    if path.exists(): raise FileExistsError(path)
    path.write_text(text.rstrip()+"\n",encoding="utf-8")


def main()->int:
    freeze=load(ROOT/"freeze/stage02jw_input_freeze_manifest.json"); formulas=load(ROOT/"blind_family_materialization/blind_family_formulas.json"); physical=load(ROOT/"reference_qualification/physical_preflight.json"); ref=load(ROOT/"reference_qualification/reference_qualification.json"); targets=load(ROOT/"target_qualification/blind_target_candidates.json"); core=load(ROOT/"target_qualification/target_core_qualification.json"); paths=load(ROOT/"target_qualification/resolution_support_qualification_retry1.json"); cons=load(ROOT/"conservation/pair_only_conservation.json"); qc=load(ROOT/"qc/quality_control_results.json"); inv=load(ROOT/"canonical_records/canonical_inventory.json"); reg=load(ROOT/"regularity_diagnostics/diagnostic_registry.json"); lineage=load(ROOT/"lineage/family_lineage_registry.json"); leakage=load(ROOT/"leakage/leakage_graph.json"); split=load(ROOT/"splits/prefrozen_split_manifest.json"); norm=load(ROOT/"normalization/train_only_graph_balanced_statistics.json"); elig=load(ROOT/"eligibility/record_eligibility_results.json"); retry=load(ROOT/"qc/infrastructure_retry_log.json")
    changed=[]; missing=[]
    for rel,expected in freeze["historical_file_hashes_before_stage02jw"].items():
        path=REPO/rel
        if not path.exists(): missing.append(rel)
        elif sha(path)!=expected: changed.append({"path":rel,"expected":expected,"actual":sha(path)})
    forbidden=[]
    for path in ROOT.rglob("*"):
        if path.is_file() and path.suffix.lower() in {".pt",".pth",".ckpt",".onnx",".h5",".keras"}: forbidden.append(str(path.relative_to(REPO)))
    integrity={"audit_version":"stage02jw-final-integrity-1.0.0","historical_file_count":freeze["historical_file_count"],"historical_files_checked":len(freeze["historical_file_hashes_before_stage02jw"]),"historical_missing_count":len(missing),"historical_changed_count":len(changed),"missing":missing,"changed":changed,"all_historical_hashes_unchanged":not missing and not changed,"forbidden_model_artifact_count":len(forbidden),"forbidden_model_artifacts":forbidden,"training_executed":False,"model_implemented":False,"performance_evaluated":False,"status":"PASS" if not missing and not changed and not forbidden else "FAIL"}
    write(ROOT/"freeze/stage02jw_final_integrity_audit.json",json.dumps(integrity,indent=2,sort_keys=True)+"\n")
    formula_rows="\n".join(f"| {x['family_id']} | {x['root_seed']} | {x['role']} | `{x['formula_hash']}` | `{x['derivative_hash']}` |" for x in formulas["families"])
    phys_rows=[r for f in physical["families"] for r in f["rows"]]; ref_rows=[r for f in ref["families"] for r in f["rows"]]; cons_rows=[r for f in cons["families"] for r in f["rows"]]
    rho_min=min(x["rho_min"] for x in phys_rows); rho_max=max(x["rho_max"] for x in phys_rows); mach=max(x["Mach_max"] for x in phys_rows); ref_l2=max(x["pair_agreement"]["normalized_L2"] for x in ref_rows); ref_linf=max(x["pair_agreement"]["normalized_Linf"] for x in ref_rows); force=max(x["normalized_total_target_force_residual"] for x in cons_rows); projection=max(x["general_antisymmetric"]["normalized_projection_residual"] for x in cons_rows)
    target_l2=[x["target_metrics"]["L2_particle_rms"] for x in targets["candidates"]]; p_any=[x["prospective_p_any"] for x in reg["rows"]]
    common="""\n\n边界声明：本阶段没有模型实现、Transformer、attention、优化器、训练、验证/测试性能评价或 benchmark claim。Stage 01 `V2_QUALIFICATION_FAIL`、`FINITE_RESOLUTION_DOMINANT` 与 viscosity operator form `NOT CONFIRMED` 均未改变。\n"""
    reports={
    "stage02jw_freeze_and_scope.md":f"""# Stage 02J-W Freeze and Scope\n\nStage 02J-V 的不可逆结论 `REGULARITY_HARD_GATE_ROUTE_TERMINATED` 已保留。资格合同在 blind formula 物化前冻结，hash 为 `{freeze['eligibility_contract_hash']}`。\n\n- regularity_hard_gate_permitted: `false`\n- regularity_diagnostic_only: `true`\n- generator source hash: `{freeze['blind_generator_source_hash']}`\n- generator configuration hash: `{freeze['blind_generator_configuration_hash']}`\n- 历史冻结文件: {freeze['historical_file_count']}\n- 历史状态: {json.dumps(freeze['historical_statuses'],ensure_ascii=False)}\n"""+common,
    "stage02jw_eligibility_contract.md":"""# Stage 02J-W Eligibility Contract\n\n`blind_dataset_eligibility_contract_v1_0.yaml` 在任何 blind formula 物化前生成并冻结。每条记录必须通过 15 项非-regularity 硬门；regularity 指标没有 reject、upgrade、split 或 normalization 决策权。整族采用 5/5 all-or-none，且 `manual_override_permitted=false`。\n"""+common,
    "stage02jw_blind_family_materialization.md":f"""# Stage 02J-W Blind Family Materialization\n\n四个冻结 blind family 均以固定 seed 单次物化，无替换、重抽或结果依赖筛选。\n\n| Family | Root seed | Frozen role | Formula hash | Derivative hash |\n|---|---:|---|---|---|\n{formula_rows}\n\n每族固定 5 个完整图：N12/H2.6、N16/H2.6、N20/H2.6、N16/H2.2、N16/H3.0；总计 20 个 candidate。rho/ux/uy 精确公式、mode inventory、解析导数定义与界已保存。\n"""+common,
    "stage02jw_reference_qualification.md":f"""# Stage 02J-W Reference Qualification\n\nPhysical preflight 为 4/4 family、20/20 case PASS。采样范围 `rho=[{rho_min:.12g}, {rho_max:.12g}] kg m^-3`，最大 Mach={mach:.12g}。closed-form grad(p)、laplacian(u) 与总解析加速度均通过 Fourier spectral differentiation 独立检查。\n\nPrimary 为 family-specific Fourier reference，secondary 为 family-specific analytic reference。Stage 02H 阈值直接读取；20/20 reference PASS。最大 normalized L2={ref_l2:.3e}，最大 normalized Linf={ref_linf:.3e}。没有 finite-difference 或 temporal derivative reference。\n"""+common,
    "stage02jw_target_qualification.md":f"""# Stage 02J-W Target Qualification\n\n目标严格采用 `delta_a = a_FOURIER - a_SPH`，符号为 `a_reference_minus_a_sph`；node label 为 `y_i=m_i delta_a_i`。20/20 target core PASS，L2 范围为 [{min(target_l2):.12g}, {max(target_l2):.12g}] m s^-2。\n\n四族 resolution path 的四项冻结非-regularity 规则全部 PASS；四族 support path 的六项规则全部 PASS。未计算或宣称 convergence order。初次 support retention 失败来自空集语义错误；受控 retry 仅将“没有待保留边”的情形判为 vacuous PASS，原失败保留，目标前后 hash 一致={str(retry['source_target_unchanged']).lower()}，无科学阈值变化。\n"""+common,
    "stage02jw_conservation_qualification.md":f"""# Stage 02J-W Conservation Qualification\n\n20/20 target 通过 pair-only conservation。最大 normalized total target-force residual={force:.3e}，最大 general antisymmetric incidence projection residual={projection:.3e}，均不超过 1e-10。central-pair 与 torque 仅作 diagnostic。\n\n没有 target mean subtraction、projection writeback、edge-pair label、node residual head 或 hybrid architecture。\n"""+common,
    "stage02jw_regularity_diagnostics.md":f"""# Stage 02J-W Regularity Diagnostics\n\n20 个记录均登记 historical v0.1 ratio、v0.2 S_h、v0.3 M_h/D_h 及 prospective p_mag/p_dir/p_any；p_any 范围为 [{min(p_any):.12g}, {max(p_any):.12g}]。每个字段均标记 `regularity_role=diagnostic_only` 与 `eligibility_effect=none`。\n\n受影响的 eligibility、split、normalization 决策数均为 0；没有 v0.5、smoothness threshold、permutation hard gate 或 graph-TV eligibility gate。历史 v0.1–v0.4 证据未删除。\n"""+common,
    "stage02jw_graph_materialization.md":f"""# Stage 02J-W Graph Materialization\n\n{inv['record_count']}/20 个 complete-particle-graph records 已物化。严格使用 Stage 02B core schema、冻结 Stage 02J extension schema 与 Stage 02J canonical serializer。为满足冻结 extension schema 的 const，record 内 `dataset_version=controlled_regular_pair_scope_v0_1` 仅作为 schema compatibility identifier；实际 collection identity 由 manifest 冻结为 `blind_multifamily_pair_scope_v1_0`。\n\n序列化采用固定字段顺序、big-endian float64/int64、canonical particle/edge order 和 byte SHA-256。double serialization、decode/re-encode、state/graph/target/force roundtrip 均 PASS。QC: {qc['record_count']}/20 PASS，hard failures={qc['hard_failure_count']}。无 edge label。\n"""+common,
    "stage02jw_leakage_and_split.md":f"""# Stage 02J-W Leakage and Split\n\nLineage registry 含 {lineage['family_count']} 个互相独立 family。每族 5 个 configuration records 构成一个 component，不同 family 无共享 seed、formula ancestry、restart、resample 或 direct lineage。共享 EOS/SPH/Fourier/serializer/domain 不视为 lineage。\n\nLeakage graph 恰有 {leakage['connected_component_count']} 个 disconnected components，cross-family edges={leakage['cross_family_edge_count']}。冻结 family split 为 train 10、validation 5、test 5；无 cross-split path，未采用 particle/edge/patch 或 resolution/support 伪独立 split。\n"""+common,
    "stage02jw_normalization.md":f"""# Stage 02J-W Normalization\n\nNormalization 仅在 20 records、4 components 与 split 全部 PASS 后拟合。输入严格为 BLIND_FAMILY_01/02 的 {norm['train_record_count']} 个 train full graphs，并采用 `{norm['fitting_rule']}`。\n\n统计覆盖 position/domain、displacement/h、distance/h、velocity/cs、density deviation/rho0、pressure/(rho0 cs^2)、h/domain 与 mass/(rho0 domain area)。validation、test、历史 PV/CROSSMODE/DIAGONAL/MIXED、jitter、target、reference 和 target-derived quantities 全部排除。statistics hash: `{norm['statistics_hash']}`。\n"""+common,
    "stage02jw_eligibility_report.md":f"""# Stage 02J-W Eligibility Report\n\n资格结果：eligible={elig['eligible_count']}/20，diagnostic={elig['diagnostic_count']}，rejected={elig['rejected_count']}。每条记录的 15/15 条件均 PASS，`eligible_for_future_training=true`，`manual_override_permitted=false`。\n\nRegularity 不在 15 项 eligibility gate 中。历史 Stage02J PV、Stage02J-R candidates、jitter 与 Stage01 R3 均保持隔离，未进入 split 或 normalization。此资格只授权未来架构资格审查，不是训练授权或性能结论。\n"""+common,
    "stage02jw_final_report.md":f"""# Stage 02J-W Final Report\n\n## Final status\n\n`BLIND_MULTIFAMILY_DATASET_READY`\n\n有限授权：`Stage 02K — Pair-Force PIO Architecture Qualification`。\n\n## Qualification closure\n\n1. Stage02J-V `REGULARITY_HARD_GATE_ROUTE_TERMINATED` 保持不变。\n2. Eligibility contract v1.0 已预先冻结；regularity 仅 diagnostic。\n3. Blind generator source/config hash 与 Stage02J-T/V 一致。\n4. 四个冻结 formula 按原 seed/role 单次物化，无替换。\n5. Physical preflight 4/4 PASS；reference 20/20 PASS。\n6. Target core 20/20 PASS；四族 resolution/support consistency PASS。\n7. Pair-only conservation 20/20 PASS；没有目标改写。\n8. 20/20 graph records 完整物化且 canonical QC PASS。\n9. Regularity registry 覆盖 20 records，eligibility effect 为 none。\n10. Lineage 独立；leakage graph 恰为 4 个 components。\n11. Prefrozen split 为 train/validation/test=10/5/5，无跨 split lineage。\n12. Graph-balanced normalization 仅使用 10 个 train graphs。\n13. Eligibility 为 20/20 PASS。\n14. 历史数据均保持 diagnostic/independent-validation 隔离。\n15. Stage02J compatibility schema 字段未改，collection identity 在 manifest 中独立冻结。\n16. 受控 infrastructure retry 数=1；原失败、前后 hash 与 target unchanged evidence 均保留。\n17. 历史哈希复核：{integrity['historical_files_checked']}/{integrity['historical_file_count']} checked，changed={integrity['historical_changed_count']}，missing={integrity['historical_missing_count']}，status={integrity['status']}。\n18. 无模型、无训练、无 optimizer、无性能评价、无 benchmark claim。\n\n## Boundary preservation\n\nStage 02J `CONTROLLED_REGULAR_DATASET_NOT_READY`、Stage02J-R `MULTIFAMILY_CONTROLLED_DATASET_NOT_READY`、Stage02J-S `VERSIONED_MULTIFAMILY_DATASET_NOT_READY`、Stage02J-T `REGULARITY_GATE_V03_NOT_QUALIFIED` 与 Stage02J-V route termination 均未覆盖。Stage01 结论与 viscosity operator 未确认状态不变。\n"""}
    for name,text in reports.items(): write(REPORTS/name,text)
    report_rows=[{"path":str((REPORTS/name).relative_to(REPO)),"sha256":sha(REPORTS/name),"byte_count":(REPORTS/name).stat().st_size} for name in reports]
    final={"manifest_version":"stage02jw-final-1.0.0","status":"BLIND_MULTIFAMILY_DATASET_READY","stage02k_authorized":True,"report_count":len(report_rows),"reports":report_rows,"dataset_manifest_sha256":sha(ROOT/"manifests/stage02jw_dataset_manifest.json"),"historical_integrity_audit_sha256":sha(ROOT/"freeze/stage02jw_final_integrity_audit.json"),"eligibility_count":elig["eligible_count"],"record_count":inv["record_count"],"leakage_component_count":leakage["connected_component_count"],"no_model":True,"no_training":True,"no_performance_evaluation":True}
    write(ROOT/"manifests/stage02jw_final_manifest.json",json.dumps(final,indent=2,sort_keys=True)+"\n")
    print(json.dumps({"reports":len(reports),"historical_integrity":integrity["status"],"status":final["status"]},sort_keys=True)); return 0

if __name__=="__main__": raise SystemExit(main())
